const paths={chat:'M21 11a8 8 0 0 1-8 8H4l-3 3V11a10 10 0 0 1 20 0Z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',gear:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',edit:'M14 5H4v15h15V10M10 14l2-5 7-7 3 3-7 7Z',mic:'M9 5a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0ZM5 11v2a7 7 0 0 0 14 0v-2M12 20v3M8 23h8',mute:'M3 3l18 18M9 4a3 3 0 0 1 6 1v7M9 9v4a3 3 0 0 0 5 2M5 11v2a7 7 0 0 0 12 5M19 11v2M12 20v3M8 23h8',arrow:'M12 20V4M5 11l7-7 7 7',chevron:'M9 4l8 8-8 8',back:'M15 4l-8 8 8 8',cube:'M12 2 2 7v10l10 5 10-5V7ZM2 7l10 5 10-5M12 12v10M7 4.5l10 5',skill:'M12 5a2.5 2.5 0 1 0 0-5 2.5 2.5 0 0 0 0 5ZM6 23l2-9-4-3 2-4 6 2 6-2 2 4-4 3 2 9M8 14h8',video:'M3 4h18v16H3ZM10 8l6 4-6 4Z',close:'M5 5l14 14M19 5 5 19',phone:'M3 16c4-6 14-6 18 0l-3 5-4-2v-3h-4v3l-4 2Z',wave:'M3 10v4M7 6v12M12 3v18M17 6v12M21 10v4',plus:'M12 4v16M4 12h16',timer:'M10 1h4M12 5a8 8 0 1 0 0 16 8 8 0 0 0 0-16ZM12 8v5l3 2',upload:'M12 16V2M7 7l5-5 5 5M4 12v10h16V12'};
Object.assign(paths,{camera:'M3 6h5l2-3h4l2 3h5v14H3ZM12 9a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',photo:'M3 3h18v18H3ZM3 17l6-7 5 5 3-3 4 5M16 6h1',clip:'M8 15l8-8a3 3 0 0 1 4 4L9 22a5 5 0 0 1-7-7L14 3a2 2 0 0 1 3 3L6 17',puzzle:'M3 4h6a3 3 0 1 1 6 0h6v6a3 3 0 1 0 0 6v5h-6a3 3 0 1 0-6 0H3v-5a3 3 0 1 0 0-6Z',glasses:'M2 11l2-6h3M22 11l-2-6h-3M2 11h7l2 2h2l2-2h7v5a3 3 0 0 1-3 3h-1a4 4 0 0 1-4-4v-2M2 11v5a3 3 0 0 0 3 3h1a4 4 0 0 0 4-4v-2',translate:'M3 5h12M9 2v3M5 8c1 5 4 7 8 9M13 5c0 5-4 10-10 13M14 22l4-11 4 11M16 18h4'});
const icon=(name,extra='')=>window.BrivanyIcons?.[name]?.replace('<svg',`<svg class="icon ${extra}" aria-hidden="true"`)||`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.chat}"/></svg>`;
const app=document.querySelector('#app'),phone=document.querySelector('#phone');let tab='chat',detail=null,live=false,muted=false,messages=[],practice='Presentación',toastTimer,light=false,toolsOpen=false,chatAttachment=null,translationMode='Directa',translationVoice='Auto',translationActive=false;
const safe=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let drawerOpen=false,searchOpen=false,currentChat=crypto.randomUUID(),chatHistory=[],chatSearch='',liveMinimized=false,liveSettings=false,settingsSheet=false;
let chatAccount='guest';
function historyKey(){return 'brivany.iphone.preview.chats.'+chatAccount}
function setChatAccount(account){
 chatAccount=account||'guest';currentChat=crypto.randomUUID();messages=[];chatHistory=[];drawerOpen=false;live=false;
 try{const saved=JSON.parse(localStorage.getItem(historyKey())||'[]');if(Array.isArray(saved))chatHistory=saved.filter(c=>typeof c.id==='string'&&typeof c.title==='string'&&c.title.length<=100&&Array.isArray(c.messages)&&c.messages.length<=200&&c.messages.every(m=>['user','assistant'].includes(m.role)&&typeof m.text==='string'&&m.text.length<=12000)).slice(0,100);if(chatHistory[0]){currentChat=chatHistory[0].id;messages=chatHistory[0].messages.map(m=>({...m}))}}catch{}
}
setChatAccount(null);
function saveConversation(id,thread){if(thread.length){const entry={id,title:thread.find(m=>m.role==='user')?.text.slice(0,65)||'Conversación',messages:thread.slice(-200).map(m=>({...m})),updated:Date.now()};chatHistory=[entry,...chatHistory.filter(c=>c.id!==id)].slice(0,100)}try{localStorage.setItem(historyKey(),JSON.stringify(chatHistory))}catch{toast('El almacenamiento local está lleno.')}}
function saveHistory(){saveConversation(currentChat,messages)}
function newChat(){saveHistory();currentChat=crypto.randomUUID();messages=[];chatAttachment=null;toolsOpen=false;drawerOpen=false;tab='chat';detail=null;render()}
function chatList(){const matches=chatHistory.filter(c=>!chatSearch||c.title.toLocaleLowerCase().includes(chatSearch.toLocaleLowerCase()));return matches.map(c=>`<button class="history-chat ${c.id===currentChat?'active':''}" data-chat="${safe(c.id)}">${safe(c.title)}</button>`).join('')||'<p class="empty-history">Aún no hay chats.</p>'}
function renderDrawer(){return `<div class="drawer-scrim" data-action="close-drawer"></div><aside class="chat-drawer" aria-label="Chats de Melodi"><header><h2>Melodi</h2><button class="icon-button" data-action="search-chats" aria-label="Buscar conversaciones">${icon('search')}</button></header>${searchOpen?`<input id="chat-search" class="drawer-search" placeholder="Buscar conversaciones" aria-label="Buscar conversaciones" value="${safe(chatSearch)}">`:''}<button class="drawer-link" data-drawer-tab="modules">${icon('grid')}Módulos</button><div class="history-label">Chats</div><div class="chat-list" id="chat-list">${chatList()}</div><footer><button class="pill new-chat" data-action="new">${icon('edit')}Nuevo chat</button><button class="icon-button drawer-settings" data-drawer-tab="settings" aria-label="Ajustes">${icon('gear')}</button></footer></aside>`}
const wordmark='<div class="wordmark">brivany<span>.</span></div>';
const tabs=()=>`<nav class="tab-zone" aria-label="Navegación de Brivany"><div class="tabs">${[['modules','grid','Módulos'],['chat','chat','Melodi'],['settings','gear','Ajustes']].map(([id,i,name])=>`<button class="tab ${tab===id?'active':''}" data-tab="${id}" aria-label="${name}" aria-current="${tab===id?'page':'false'}">${icon(i)}${name}</button>`).join('')}</div></nav>`;
const header=()=>`<header class="app-header">${tab==='chat'?`<button class="icon-button" data-action="chats" aria-label="Abrir chats de Melodi">${icon('menu')}</button>`:''}${wordmark}${tab==='chat'?`<button class="icon-button" data-action="new" aria-label="Nueva conversación">${icon('edit')}</button>`:''}</header>`;
const detailHeader=name=>`<header class="detail-header"><button class="icon-button back" data-action="back" aria-label="Volver">${icon('back')}</button>${name}</header>`;
function render(){
 let content='';
 if(detail){content=renderDetail();}
 else if(tab==='chat')content=`${header()}<div class="content chat-content">${messages.length?`<div class="messages">${messages.map(m=>`<div class="message ${m.role}">${safe(m.text)}</div>`).join('')}</div>`:'<div class="empty"><h2>¿Qué creamos hoy?</h2></div>'}</div><div class="compose-zone">${chatAttachment?`<div class="attachment">${icon('clip')}<span>${safe(chatAttachment)}</span><button class="icon-button" data-action="remove-attachment" aria-label="Quitar adjunto">${icon('close')}</button></div>`:''}${toolsOpen?renderTools():''}<form class="composer"><button type="button" class="attach-button" data-action="tools" aria-label="Herramientas del chat" aria-expanded="${toolsOpen}">${icon('plus')}</button><textarea id="draft" rows="1" placeholder="Pregunta a Melodi" aria-label="Mensaje para Melodi"></textarea><button type="button" class="voice-button live-button" id="compose-action" data-action="live" aria-label="Iniciar modo de voz">${icon('wave')}</button><button type="submit" class="send-button" id="send-message" aria-label="Enviar mensaje" hidden>${icon('arrow')}</button></form><input type="file" id="chat-file" hidden><input type="file" id="chat-photo" accept="image/*" hidden><input type="file" id="chat-camera" accept="image/*" capture="environment" hidden></div>`;
 else if(tab==='modules')content=`${header()}<div class="content"><section class="section"><h2>Módulos</h2>${[['glasses','glasses','Meta Glasses','Conectar tus gafas'],['translation','translate','Traducción en vivo','Audio y video'],['skills','skill','Human-skills','Practicar y preparar'],['spaces','cube','Espacios','Modelos 3D'],['video','video','Video','Reproducir y extraer audio']].map(([id,i,name,desc])=>`<button class="module-card" data-detail="${id}">${icon(i)}<div><strong>${name}</strong><small>${desc}</small></div>${icon('chevron','chevron')}</button>`).join('')}</section></div>`;
 else content=`<div class="content settings-content"><section class="section"><h2>Ajustes</h2><div class="group"><button class="row" data-detail="connection"><span>Cuenta Brivany</span><span class="value">${window.BrivanyAccountPreview?.signedIn?'Conectada':'Iniciar sesión'} ${icon('chevron')}</span></button><div class="row"><span>Voz</span><span class="value">Melodi</span></div></div><div class="group"><button class="row" data-action="appearance"><span>Apariencia</span><span class="value">${light?'Clara':'Oscura'} ${icon('chevron')}</span></button></div><div class="group"><button class="row" data-action="privacy"><span>Privacidad</span><span class="value">${icon('chevron')}</span></button><button class="row" data-action="terms"><span>Condiciones de uso</span><span class="value">${icon('chevron')}</span></button><div class="row"><span>Versión</span><span class="value">0.1.0</span></div></div></section></div>`;
 app.classList.toggle('drawer-open',drawerOpen);app.innerHTML=`<div class="app-page">${content}${tabs()}</div>`+(drawerOpen?renderDrawer():'')+(settingsSheet?renderAppearanceSheet():'')+(live?renderLive():'');bind();if(detail==='privacy'||detail==='terms')loadLegal();window.BrivanyAccountPreview?.enhance();
}
function renderDetail(){
 if(detail==='connection'&&window.BrivanyAccountPreview)return window.BrivanyAccountPreview.page();
 if(detail==='privacy'||detail==='terms')return `${detailHeader(detail==='privacy'?'Privacidad':'Condiciones de uso')}<div class="content legal-content" id="legal-content" aria-busy="true"><div class="legal-loader"></div></div>`;
 if(detail==='glasses')return `${detailHeader('Meta Glasses')}<div class="content"><section class="detail-area"><div class="glasses-visual">${icon('glasses')}</div><h2>Meta Glasses</h2><div class="group"><div class="row"><span>Gafas</span><span class="value">Sin conectar</span></div></div><button class="pill primary wide" data-action="pair-glasses">Vincular gafas</button></section></div>`;
 if(detail==='translation')return `${detailHeader('Traducción en vivo')}<div class="content"><section class="detail-area"><div class="segmented">${['Directa','Preproducción','Navegador'].map(m=>`<button class="${translationMode===m?'active':''}" data-translation-mode="${m}">${m}</button>`).join('')}</div><div class="translation-controls"><select aria-label="Idioma de traducción" class="language-select"><option>English</option><option>Español</option><option>Français</option></select><div class="segmented voice-segment">${['Auto','Masculina','Femenina'].map(v=>`<button class="${translationVoice===v?'active':''}" data-translation-voice="${v}">${v}</button>`).join('')}</div></div><div class="translation-caption" aria-live="polite">${translationActive?'Escuchando…':''}</div><div class="translation-footer"><button class="pill" data-action="translation-source">${icon('video')}Elegir video</button><button class="pill primary" data-action="translation-toggle">${translationActive?'Detener':'Iniciar'}</button></div></section></div>`;
 if(detail==='skills')return `${detailHeader('Human-skills')}<div class="content"><section class="detail-area"><div class="segmented">${['Presentación','Entrevista','Idiomas'].map(p=>`<button data-practice="${p}" class="${practice===p?'active':''}">${p}</button>`).join('')}</div><h2>${practice==='Presentación'?'Tu idea en un minuto.':practice==='Entrevista'?'Prepara tu respuesta.':'Una conversación,<br>otro idioma.'}</h2><textarea id="practice-text" aria-label="Texto para practicar" placeholder="Escribe tu idea…"></textarea><div class="actions"><button class="pill" data-action="timer">${icon('timer')}Cronómetro</button><button class="pill primary" data-action="review">Revisar con Melodi</button></div></section></div>`;
 if(detail==='spaces')return `${detailHeader('Espacios')}<div class="content"><section class="detail-area"><h2>Espacios</h2><button class="pill wide" data-action="import-model">${icon('plus')}Importar modelo USDZ</button><input type="file" id="model-file" accept=".usdz" hidden><div id="model-result"></div></section></div>`;
 if(detail==='video')return `${detailHeader('Video')}<div class="content"><section class="detail-area"><h2>Video</h2><button class="pill wide" data-action="import-video">${icon('plus')}Elegir video</button><input type="file" id="video-file" accept="video/*" hidden><video id="video-preview" controls playsinline style="width:100%;border-radius:18px;margin-top:24px;display:none"></video><div id="video-result"></div></section></div>`;
 return `${detailHeader('Conexión')}<div class="content"><section class="detail-area"><div class="group"><div class="row"><span>Servicio</span><span class="value">Brivany</span></div><div class="row"><span>Estado</span><span class="value">Sin vincular</span></div><button class="row link" data-action="import-connection">Importar conexión</button></div><p class="info">Elige el archivo .brivanyconnection de este equipo en la app nativa.</p></section></div>`;
}
function renderTools(){return `<div class="tools-menu" role="menu">${[['camera','camera','Cámara'],['photos','photo','Fotos'],['files','clip','Archivos'],['addons','puzzle','Complementos']].map(([id,i,name])=>`<button type="button" role="menuitem" data-tool="${id}"><span>${name}</span>${icon(i)}</button>`).join('')}<div class="agent-row"><span>Melodi</span><span>✓</span></div></div>`;}
function renderLive(){return `<section class="live-view ${muted?'muted':''}" aria-label="Conversación de voz con Melodi"><header><button class="icon-button ${liveMinimized?'expanded':''}" data-action="minimize-live" aria-label="${liveMinimized?'Volver al modo de voz':'Ver conversación'}">${icon('down')}</button><span>${liveMinimized?'Conversación con Melodi':'Melodi Live'}</span><button class="icon-button" data-action="live-settings" aria-label="Ajustes de voz">${icon('sliders')}</button></header>${liveMinimized?`<div class="live-transcript content">${messages.length?messages.map(m=>`<div class="message ${m.role}">${safe(m.text)}</div>`).join(''):'<p class="empty-history">Aún no hay mensajes.</p>'}</div><button class="mini-call" data-action="minimize-live"><i class="mini-orb"></i><span>Melodi<small>Volver al modo de voz</small></span>${icon('arrow')}</button>`:`<div class="live-body"><div class="orb-zone"><div class="orb"><div class="orb-ribbon"></div></div></div><p class="live-status">${muted?'Micrófono apagado':'Te escucho'}</p></div>`}<form class="live-controls"><div class="live-composer"><textarea id="live-draft" rows="1" placeholder="Escribe a Melodi" aria-label="Escribe a Melodi"></textarea><button class="live-send" type="submit" aria-label="Enviar en Live" hidden>${icon('arrow')}</button></div><button type="button" class="live-mic" data-action="mute" aria-label="${muted?'Activar':'Silenciar'} micrófono">${icon(muted?'mute':'mic')}</button><button type="button" class="end" data-action="close-live" aria-label="Finalizar conversación">${icon('close')}</button></form>${liveSettings?`<div class="sheet-backdrop" data-action="live-settings"></div><section class="bottom-sheet" role="dialog" aria-modal="true" aria-label="Voz de Melodi"><div class="sheet-handle"></div><h3>Voz</h3><button class="sheet-choice" data-action="live-settings"><span>Melodi</span>${icon('check')}</button><button class="sheet-close" data-action="live-settings">Listo</button></section>`:''}</section>`;}
function renderAppearanceSheet(){return `<div class="sheet-backdrop" data-action="appearance"></div><section class="bottom-sheet" role="dialog" aria-modal="true" aria-label="Apariencia"><div class="sheet-handle"></div><h3>Apariencia</h3>${[['dark','Oscura'],['light','Clara']].map(([id,title])=>`<button class="sheet-choice" data-theme="${id}"><span>${title}</span>${(light?'light':'dark')===id?icon('check'):''}</button>`).join('')}<button class="sheet-close" data-action="appearance">Listo</button></section>`;}
async function loadLegal(){const target=document.querySelector('#legal-content'),page=detail;try{const response=await fetch('legal/'+(page==='privacy'?'privacidad':'condiciones')+'.html');if(!response.ok)throw Error();const html=await response.text();if(detail!==page||!target.isConnected)return;const parsed=new DOMParser().parseFromString(html,'text/html');parsed.querySelectorAll('script,iframe,object').forEach(n=>n.remove());target.replaceChildren(...parsed.body.childNodes);target.setAttribute('aria-busy','false');target.querySelectorAll('a').forEach(a=>a.addEventListener('click',event=>{event.preventDefault();const href=a.getAttribute('href')||'';if(href.startsWith('#'))target.querySelector(href)?.scrollIntoView({behavior:'smooth'});else if(href.startsWith('/privacidad')){detail='privacy';render()}else if(href.startsWith('/condiciones')){detail='terms';render()}else if(href.startsWith('mailto:')){navigator.clipboard?.writeText(href.slice(7));toast('Correo copiado.')}}))}catch{if(target.isConnected){target.textContent='No se pudo cargar el documento.';target.setAttribute('aria-busy','false')}}}
function toast(message){clearTimeout(toastTimer);document.querySelector('.toast')?.remove();const node=document.createElement('div');node.className='toast';node.textContent=message;app.append(node);toastTimer=setTimeout(()=>node.remove(),3800);}
function send(){if(window.BrivanyAccountPreview?.signedIn)return window.BrivanyAccountPreview.send('chat');const field=document.querySelector('#draft'),text=field?.value.trim();if(!text&&!chatAttachment)return;messages.push({role:'user',text:[text,chatAttachment?'📎 '+chatAttachment:''].filter(Boolean).join('\n')});chatAttachment=null;toolsOpen=false;saveHistory();render();}
function bind(){
 app.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;detail=null;render()});app.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{detail=b.dataset.detail;render()});app.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>{practice=b.dataset.practice;render()});
 app.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{switch(b.dataset.action){case'new':messages=[];toolsOpen=false;render();break;case'back':detail=null;render();break;case'live':toolsOpen=false;live=true;render();break;case'close-live':live=false;render();break;case'mute':muted=!muted;render();break;case'send':send();break;case'tools':{const draft=document.querySelector('#draft')?.value||'';toolsOpen=!toolsOpen;render();document.querySelector('#draft').value=draft;updateComposer();break}case'remove-attachment':chatAttachment=null;render();break;case'dictate':toast('El dictado se probará con el micrófono en la app nativa.');break;case'pair-glasses':toast('La vinculación real de gafas se conectará en la app nativa.');break;case'translation-toggle':translationActive=!translationActive;render();break;case'translation-source':toast('En iPhone podrás elegir el video desde Archivos.');break;case'privacy':detail='privacy';tab='settings';render();break;case'terms':detail='terms';tab='settings';render();break;case'import-model':document.querySelector('#model-file').click();break;case'import-video':document.querySelector('#video-file').click();break;case'import-connection':toast('La vinculación se realiza en la app de iPhone.');break;case'timer':b.textContent='00:00';let t=0;const interval=setInterval(()=>{if(!b.isConnected){clearInterval(interval);return}t++;b.textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0')},1000);b.disabled=true;break;case'review':{const text=document.querySelector('#practice-text')?.value.trim();if(!text){toast('Escribe el texto que quieres practicar.');break}messages.push({role:'user',text:'Revisemos esta idea: '+text});tab='chat';detail=null;render();break}}});
 app.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{const target={camera:'#chat-camera',photos:'#chat-photo',files:'#chat-file'}[b.dataset.tool];if(target){document.querySelector(target).click()}else{toolsOpen=false;tab='settings';detail='connection';render()}});
 app.querySelectorAll('[data-translation-mode]').forEach(b=>b.onclick=()=>{translationMode=b.dataset.translationMode;translationActive=false;render()});
 app.querySelectorAll('[data-translation-voice]').forEach(b=>b.onclick=()=>{translationVoice=b.dataset.translationVoice;render()});
 const field=app.querySelector('#draft');field?.addEventListener('input',updateComposer);field?.addEventListener('focus',updateComposer);field?.addEventListener('blur',()=>requestAnimationFrame(updateComposer));app.querySelector('#compose-action')?.addEventListener('mousedown',e=>e.preventDefault());app.querySelector('.composer')?.addEventListener('submit',e=>{e.preventDefault();send()});
 field?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}});
 app.querySelector('#theme')?.addEventListener('change',e=>setTheme(e.target.value==='light'));
 app.querySelector('#video-file')?.addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;const video=document.querySelector('#video-preview');video.src=URL.createObjectURL(file);video.style.display='block';const label=document.createElement('p');label.className='info';label.textContent=file.name;document.querySelector('#video-result').replaceChildren(label)});
 app.querySelector('#model-file')?.addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;const label=document.createElement('p');label.className='info';label.textContent=file.name+' · El visor 3D se abre con Quick Look en iPhone.';document.querySelector('#model-result').replaceChildren(label)});
 app.querySelectorAll('#chat-file,#chat-photo,#chat-camera').forEach(input=>input.addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;const draft=document.querySelector('#draft')?.value||'';chatAttachment=file.name;toolsOpen=false;render();document.querySelector('#draft').value=draft;updateComposer()}));
 const actions={
  new:newChat,chats:()=>{toolsOpen=false;drawerOpen=true;render()},'close-drawer':()=>{drawerOpen=false;render()},
  'search-chats':()=>{searchOpen=!searchOpen;render();document.querySelector('#chat-search')?.focus()},
  privacy:()=>{detail='privacy';tab='settings';render()},terms:()=>{detail='terms';tab='settings';render()},
  appearance:()=>{settingsSheet=!settingsSheet;render()},
  live:()=>{toolsOpen=false;liveSettings=false;liveMinimized=false;live=true;render()},
  'minimize-live':()=>{liveMinimized=!liveMinimized;render()},'live-settings':()=>{liveSettings=!liveSettings;render()},
  'close-live':()=>{live=false;liveSettings=false;render()}
 };
 app.querySelectorAll('[data-action]').forEach(button=>{const action=actions[button.dataset.action];if(action)button.onclick=action});
 const bindChats=()=>app.querySelectorAll('[data-chat]').forEach(button=>button.onclick=()=>{saveHistory();const chat=chatHistory.find(c=>c.id===button.dataset.chat);if(!chat)return;currentChat=chat.id;messages=chat.messages.map(m=>({...m}));drawerOpen=false;tab='chat';detail=null;render()});bindChats();
 app.querySelector('#chat-search')?.addEventListener('input',event=>{chatSearch=event.target.value;document.querySelector('#chat-list').innerHTML=chatList();bindChats()});
 app.querySelectorAll('[data-drawer-tab]').forEach(button=>button.onclick=()=>{drawerOpen=false;tab=button.dataset.drawerTab;detail=null;render()});
 app.querySelectorAll('[data-theme]').forEach(button=>button.onclick=()=>{settingsSheet=false;setTheme(button.dataset.theme==='light')});
 const liveField=app.querySelector('#live-draft');liveField?.addEventListener('input',()=>{const button=app.querySelector('.live-send');button.hidden=!liveField.value.trim();liveField.style.height='auto';liveField.style.height=Math.min(70,Math.max(20,liveField.scrollHeight))+'px'});
 const sendLive=()=>{if(window.BrivanyAccountPreview?.signedIn)return window.BrivanyAccountPreview.send('voice');const text=liveField?.value.trim();if(!text)return;messages.push({role:'user',text});saveHistory();render()};
 app.querySelector('.live-controls')?.addEventListener('submit',event=>{event.preventDefault();sendLive()});
 liveField?.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendLive()}});
}
function updateComposer(){const field=app.querySelector('#draft'),b=app.querySelector('#compose-action'),sendButton=app.querySelector('#send-message');if(!field||!b)return;const focused=document.activeElement===field;b.innerHTML=icon(focused?'mic':'wave');b.dataset.action=focused?'dictate':'live';b.classList.toggle('live-button',!focused);b.setAttribute('aria-label',focused?'Dictar mensaje':'Iniciar modo de voz');sendButton.hidden=!field.value.trim()&&!chatAttachment;field.style.height='auto';field.style.height=Math.min(115,Math.max(38,field.scrollHeight))+'px';}
function setTheme(value){light=value;phone.classList.toggle('light',light);document.querySelector('#appearance').textContent=light?'Oscuro':'Claro';if(tab==='settings')render()}
document.querySelector('#appearance').onclick=()=>setTheme(!light);
function resize(){const [w,h]=document.querySelector('#device').value.split(',').map(Number),stage=document.querySelector('.stage'),scale=Math.min((stage.clientHeight-22)/h,(stage.clientWidth-20)/w,1);phone.style.width=w+'px';phone.style.height=h+'px';phone.style.transform=`scale(${scale})`;const wrap=document.querySelector('#phone-wrap');wrap.style.width=w*scale+'px';wrap.style.height=h*scale+'px';}
document.querySelector('#device').onchange=resize;new ResizeObserver(resize).observe(document.querySelector('.stage'));render();resize();
window.addEventListener('keydown',event=>{if(event.key==='Escape'&&(drawerOpen||settingsSheet||liveSettings)){drawerOpen=false;settingsSheet=false;liveSettings=false;render()}});
